import Model from 'flarum/common/Model';
// API alanları camelCase gelir (WhoReaderResource: lastReadAt, lastReadPostNumber)
export default class UserState extends Model {
  last_read_at = (() => Model.attribute('lastReadAt'))();
  last_read_post_number = (() => Model.attribute('lastReadPostNumber'))();
  subscription = (() => Model.attribute('subscription'))();
  unread = (() => Model.attribute('unread'))();
  user = (() => Model.hasOne('user'))();
}
flarum.reg.add('framio-engagement', 'who-read/forum/models/UserState', UserState);