import app from 'flarum/forum/app';
import Modal from 'flarum/common/components/Modal';
import Button from 'flarum/common/components/Button';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import collections from '../collections';
/**
 * "Kitaplığa kaydet": Instagram'daki koleksiyonlar gibi. Kitaplığa dokununca mesaj oraya
 * kaydedilir; aynı pencereden yeni kitaplık oluşturulabilir.
 */
export default class CollectionModal extends Modal {
  newName = '';
  creating = false;
  busyId = (() => undefined)();
  oninit(vnode) {
    super.oninit(vnode);
    collections.load();
  }
  className() {
    return 'BookmarkCollectionModal Modal--small';
  }
  title() {
    return 'Kitaplığa kaydet';
  }
  content() {
    const post = this.attrs.post;
    const current = post.attribute('bookmarkCollectionId') ?? null;
    const list = collections.list;
    return m("div", {
      className: "Modal-body"
    }, !list ? m(LoadingIndicator, null) : m("div", {
      className: "BookmarkCollections-grid"
    }, m("button", {
      type: "button",
      className: 'BookmarkCollection-tile' + (post.bookmarked() && current === null ? ' is-current' : ''),
      onclick: () => this.pick(null)
    }, m("span", {
      className: "BookmarkCollection-cover is-all"
    }, m("i", {
      className: "fas fa-bookmark"
    })), m("span", {
      className: "BookmarkCollection-name"
    }, "T\xFCm kaydedilenler"), this.busyId === null ? m("i", {
      className: "fas fa-spinner fa-spin BookmarkCollection-check"
    }) : post.bookmarked() && current === null ? m("i", {
      className: "fas fa-check-circle BookmarkCollection-check"
    }) : null), list.map(c => m("button", {
      type: "button",
      key: c.id,
      className: 'BookmarkCollection-tile' + (current === c.id ? ' is-current' : ''),
      onclick: () => this.pick(c.id)
    }, m("span", {
      className: "BookmarkCollection-cover",
      style: c.cover ? {
        backgroundImage: 'url("' + c.cover + '")'
      } : undefined
    }, c.cover ? null : m("i", {
      className: "far fa-images"
    })), m("span", {
      className: "BookmarkCollection-name"
    }, c.name), m("span", {
      className: "BookmarkCollection-count"
    }, c.count, " kay\u0131t"), this.busyId === c.id ? m("i", {
      className: "fas fa-spinner fa-spin BookmarkCollection-check"
    }) : current === c.id ? m("i", {
      className: "fas fa-check-circle BookmarkCollection-check"
    }) : null))), m("form", {
      className: "BookmarkCollection-new",
      onsubmit: e => {
        e.preventDefault();
        this.create();
      }
    }, m("input", {
      className: "FormControl",
      maxlength: 80,
      placeholder: "Yeni kitapl\u0131k ad\u0131 (\xF6r. Travegolar, Otogarlar)",
      value: this.newName,
      oninput: e => this.newName = e.target.value
    }), m(Button, {
      type: "submit",
      className: "Button Button--primary",
      icon: "fas fa-plus",
      loading: this.creating,
      disabled: !this.newName.trim()
    }, "Olu\u015Ftur ve kaydet")));
  }
  pick(id) {
    if (this.busyId !== undefined) return;
    this.busyId = id;
    collections.assign(this.attrs.post, id).then(() => {
      const name = id === null ? 'Tüm kaydedilenler' : (collections.list || []).find(c => c.id === id)?.name;
      app.alerts.show({
        type: 'success'
      }, `"${name}" kitaplığına kaydedildi.`);
      this.hide();
    }).finally(() => {
      this.busyId = undefined;
      m.redraw();
    });
  }
  create() {
    const name = this.newName.trim();
    if (!name || this.creating) return;
    this.creating = true;
    collections.create(name).then(id => {
      this.newName = '';
      this.creating = false;
      this.pick(id);
    }).catch(() => {
      this.creating = false;
      m.redraw();
    });
  }
}
flarum.reg.add('framio-engagement', 'bookmarks/forum/components/CollectionModal', CollectionModal);